static int fails, checks;
static void chk(const char* n,int ok){ checks++; if(!ok)fails++; printf("  %-76s %s\n",n,ok?"ok":"FAIL"); }
static void put(u8* r,int bit,int sz,int v){ for(int i=0;i<sz;i++){ int p=bit+i; if((v>>i)&1)r[p>>3]|=(u8)(1<<(p&7)); else r[p>>3]&=(u8)~(1<<(p&7)); } }
static void feed(const u8* r,int n){ mouse_dx=mouse_dy=mouse_scroll=0; g_btn=0; hid_report_decode(0,r,n); }
static int lay(const char* nm,const u8* d,int n){ int hid=0; memset(xhid_lay,0,sizeof xhid_lay); int k=hid_parse(d,n,xhid_lay[0],HIDLAY_MAX,&hid); xhid_nlay[0]=k; xhid_hasid[0]=hid; xhid_ccn[0]=0;
  int ms=-1; for(int q=0;q<k;q++) if(xhid_lay[0][q].kind==2){ ms=q; break; }
  char b[128]; snprintf(b,sizeof b,"%s: mouse layout found",nm); chk(b,ms>=0); return ms; }
static void expect(const char* nm,const u8* d,int n,int idb,int xo,int xs,int yo,int ys,int wo,int len){
  int ms=lay(nm,d,n); if(ms<0)return; hidlay_t* L=&xhid_lay[0][ms]; char b[160];
  snprintf(b,sizeof b,"%s: x_off=%d x_sz=%d y_off=%d y_sz=%d w_off=%d (want %d %d %d %d %d)",nm,L->x_off,L->x_sz,L->y_off,L->y_sz,L->w_off,xo,xs,yo,ys,wo);
  chk(b,L->x_off==xo&&L->x_sz==xs&&L->y_off==yo&&L->y_sz==ys&&L->w_off==wo);
  int lim=(1<<(ys-1))-1; if(ys>=16)lim=32767; int vx[4]={3,0,-lim,lim}, vy[4]={-5,7,lim,-lim};
  for(int t=0;t<4;t++){ u8 r[64]; memset(r,0,sizeof r); int base=0; if(idb>=0){ r[0]=(u8)idb; base=8; }
    put(r,base+xo,xs,vx[t]); put(r,base+yo,ys,vy[t]); if(wo>=0)put(r,base+wo,8,0x55); feed(r,len);
    snprintf(b,sizeof b,"%s: dx=%d dy=%d decoded (got %d,%d)",nm,vx[t],vy[t],mouse_dx,-mouse_dy); chk(b,mouse_dx==vx[t]&&mouse_dy==-vy[t]); } }
