int main(void){
  printf("== hid_parse: X/Y layouts of real-world mouse descriptor shapes ==\n");
  expect("UsageMin X..Max Y, count 2, wheel after",D_RANGE2,sizeof D_RANGE2,-1,8,8,16,8,24,4);
  expect("UsageMin X..Max Y, count 3 (3rd field unnamed)",D_RANGE3,sizeof D_RANGE3,-1,8,8,16,8,-1,4);
  expect("UsageMin X..Max Y + Usage Wheel, count 3",D_RANGE_WHEEL,sizeof D_RANGE_WHEEL,-1,8,8,16,8,24,4);
  expect("Usage X, Usage Y, count 3 (last usage repeats)",D_XY_COUNT3,sizeof D_XY_COUNT3,-1,8,8,16,8,-1,4);
  expect("ID1 Usage X, Usage Y, 16-bit count 4",D_XY_COUNT4_ID,sizeof D_XY_COUNT4_ID,1,8,16,24,16,-1,10);
  expect("X and Y in separate Input items",D_SPLIT,sizeof D_SPLIT,-1,8,8,16,8,24,4);
  expect("ID2 12-bit packed X/Y (Y at bits 12-23)",D_12BIT,sizeof D_12BIT,2,16,12,28,12,40,7);
  expect("ID1 16-bit X/Y, Logical Min -32767",D_16BIT,sizeof D_16BIT,1,8,16,24,16,40,7);
  expect("Usage X/Y before Usage Page(Generic Desktop)",D_LATEPAGE,sizeof D_LATEPAGE,-1,8,8,16,8,-1,3);
  expect("Push/Pop around the button block",D_PUSHPOP,sizeof D_PUSHPOP,-1,8,8,16,8,-1,3);
  expect("4-byte extended usages for X/Y",D_USAGE32,sizeof D_USAGE32,-1,8,8,16,8,-1,3);
  expect("ID3 X/Y in a second Physical collection, wheel in Logical",D_PAGEINPHYS,sizeof D_PAGEINPHYS,3,8,12,20,12,32,6);
  expect("combo: keyboard ID1 then mouse ID2",D_KBD_THEN_MOUSE,sizeof D_KBD_THEN_MOUSE,2,8,8,16,8,24,5);
  { int hid=0; hidlay_t L[HIDLAY_MAX]; static const u8 noy[]={HDR,PTR,BTN3,0x05,0x01,0x09,0x30,0x15,0x81,0x25,0x7F,0x75,0x08,0x95,0x01,0x81,0x06,0xC0,0xC0};
    int k=hid_parse(noy,sizeof noy,L,HIDLAY_MAX,&hid); chk("descriptor with X but no Y yields no mouse layout",k==0); }
  { int ms=lay("QEMU usb-tablet (long item first)",D_QTABLET,sizeof D_QTABLET); if(ms>=0){ hidlay_t* L=&xhid_lay[0][ms];
    chk("usb-tablet: absolute, X/Y 16-bit 0..32767",L->abs==1&&L->x_sz==16&&L->y_sz==16&&L->x_lo==0&&L->x_hi==32767&&L->y_hi==32767&&L->w_off==40);
    u8 r[6]={1,0x00,0x40,0xFF,0x7F,0xFF}; g_absn=0; feed(r,6); chk("usb-tablet: x=16384 y=32767 -> in_abs, no relative motion, button 1, wheel -1",g_absn==1&&g_absx==16384&&g_absy==32767&&g_absxr==32767&&mouse_dx==0&&(g_btn&1)&&mouse_scroll==-1); } }
  { int ms=lay("hi-res wheel + AC Pan, 16 buttons",D_HIRES,sizeof D_HIRES); if(ms>=0){ hidlay_t* L=&xhid_lay[0][ms];
    chk("hi-res: multiplier 8, feature ID 2, 2 bytes, offsets 0 and 8, value 1",L->rm_mul==8&&L->rm_id==2&&L->rm_len==2&&L->rm_n==2&&L->rm_off[0]==0&&L->rm_off[1]==8&&L->rm_val[0]==1&&L->rm_val[1]==1);
    chk("hi-res: 16 buttons, wheel at 48, AC Pan at 56",L->btn_cnt==16&&L->w_off==48&&L->h_off==56&&L->h_sz==8&&!L->abs);
    u8 r[9]={1,0x18,0x80,0,0,0,0,1,0xFE}; mouse_hscroll=0; feed(r,9); chk("notch mode: wheel +1, pan -2, buttons 4/5 seen, button 16 parsed",mouse_scroll==1&&mouse_hscroll==-2&&g_xbtn==3);
    L->rm_on=1; mouse_hscroll=0; int tot=0, th=0; for(int t=0;t<12;t++){ u8 q[9]={1,0,0,0,0,0,0,3,0xFF}; feed(q,9); tot+=mouse_scroll; th+=mouse_hscroll; mouse_hscroll=0; }
    chk("hi-res mode: 12 x +3/8 = 4 notches (36/8, remainder kept), pan 12 x -1/8 = -1",tot==4&&th==-1);
    chk("hi-res: every report delivered as 45/120 (12 reports, 540 units), not held back to whole notches",g_hrn>=12&&g_hrsum==540);
    chk("16 buttons: mask 0x8018 delivered (side, extra, button 16)",(feed(r,9),g_btnmask==0x8018));
    L->rm_mul=7; L->w_acc=0; L->h_acc=0; g_hrsum=0; g_hrn=0; g_hrv=0; for(int t=0;t<7;t++){ u8 q[9]={1,0,0,0,0,0,0,1,0}; feed(q,9); }
    chk("hi-res multiplier 7: 7 x 1/7 notch = exactly 120 units, fraction carried between reports",g_hrsum==120&&g_hrn==7&&L->w_acc==0);
    L->rm_on=0; L->rm_mul=8; g_hrn=0; { u8 q[9]={1,0,0,0,0,0,0,1,0}; feed(q,9); } chk("notch mode does not use the hi-res path",g_hrn==0&&mouse_scroll==1); } }
  { int ms=lay("digitizer pen (tip, barrel, in-range)",D_PEN,sizeof D_PEN); if(ms>=0){ hidlay_t* L=&xhid_lay[0][ms];
    chk("pen: absolute X 0..10000 Y 0..5000",L->abs&&L->x_hi==10000&&L->y_hi==5000&&L->tip_off==0&&L->bar_off==1&&L->rng_off==2);
    u8 r[5]={0x05,0x88,0x13,0xC4,0x09}; g_absn=0; feed(r,5); chk("pen: tip+in-range at (5000,2500) -> abs + left button",g_absn==1&&g_absx==5000&&g_absy==2500&&g_btn==1);
    u8 o[5]={0x00,0,0,0,0}; g_absn=0; feed(o,5); chk("pen: out of range -> no jump to 0,0",g_absn==0); } }
  { int hid=0; memset(xhid_lay,0,sizeof xhid_lay); int k=hid_parse(D_CCLIST,sizeof D_CCLIST,xhid_lay[0],HIDLAY_MAX,&hid); xhid_nlay[0]=k; xhid_hasid[0]=hid; xhid_ccn[0]=0;
    chk("consumer array with a usage list (2-bit, logical 1..3)",k==1&&xhid_lay[0][0].cl_n==3&&xhid_lay[0][0].cc_sz==2);
    u8 r[2]={3,2}; feed(r,2); chk("consumer list: value 2 -> Volume Down (0xEA)",xhid_ccn[0]==1&&xhid_ccp[0][0]==0xEA); }
  { int ms=lay("Logical Max 0xFF (1 byte, Min 0) is 255, not -1",D_UMAX,sizeof D_UMAX); if(ms>=0){ hidlay_t* L=&xhid_lay[0][ms]; chk("unsigned logical max: absolute 0..255",L->abs&&L->x_hi==255&&L->y_hi==255); } }
  { u32 seed=0x1234567u; int rounds=0; u8 d[256], r[64];
    for(int it=0;it<200000;it++){ int n=1+(int)((seed=seed*1103515245u+12345u)>>16)%256; for(int i=0;i<n;i++){ seed=seed*1103515245u+12345u; d[i]=(u8)(seed>>16); if(i%5==0&&(seed&0x100))d[i]=(u8)("\x05\x09\x19\x29\x15\x25\x75\x95\x81\xA1\xC0\x85\xA4\xB4\xB1\xFE"[(seed>>9)&15]); }
      int hid=0; int k=hid_parse(d,n,xhid_lay[0],HIDLAY_MAX,&hid); if(k<0||k>HIDLAY_MAX){ rounds=-1; break; } xhid_nlay[0]=k; xhid_hasid[0]=hid; xhid_ccn[0]=0;
      for(int j=0;j<4;j++){ int m=(int)((seed=seed*1103515245u+12345u)>>16)%65; for(int i=0;i<m;i++)r[i]=(u8)((seed=seed*1103515245u+12345u)>>16); feed(r,m); } rounds++; }
    chk("fuzz: 200000 random descriptors x 4 random reports, no crash, layouts in bounds",rounds==200000); }
  printf("%s (%d checks, %d failed)\n",fails?"FAILURES":"ALL PASS",checks,fails); return fails?1:0; }
